Here's an example code for a Discord bot using Discord.js v14 with a single slash command, ban:

```
const { Client, SlashCommandBuilder } = require('discord.js');

const client = new Client({ intents: ['GUILDS', 'GUILD_MESSAGES', 'GUILD_MEMBERS'] });

const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a user from the server.')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('The user to ban.')
      .setRequired(true)
  );

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName, options } = interaction;

  if (commandName === 'ban') {
    const user = options.getUser('user');

    if (!user) {
      return interaction.reply('Please provide a user to ban.');
    }

    const member = interaction.guild.members.cache.get(user.id);

    if (!member) {
      return interaction.reply('The user is not in the server.');
    }

    await member.ban({ reason: 'Banned by the bot' });

    interaction.reply(`User ${user.tag} has been banned.`);
  }
});

client.login('YOUR_BOT_TOKEN');
```

